def indent_except_first(text, n):
    lines = text.split("\n")
    return "\n".join(line if i == 0 else " " * n + line for i, line in enumerate(lines))

def dedent_tabs(text):
    out = []
    for line in text.split("\n"):
        if line.startswith("\t"):
            out.append("    " + line[1:])
        else:
            out.append(line)
    return "\n".join(out)

def reindent(text, old_n, new_n):
    out = []
    prefix = " " * old_n
    for line in text.split("\n"):
        if line.startswith(prefix):
            out.append(" " * new_n + line[old_n:])
        else:
            out.append(line)
    return "\n".join(out)

def render_numbered_padded(items):
    n = len(items)
    width = len(str(n)) if n > 0 else 1
    return "\n".join(f"{str(i + 1).zfill(width)}. {item}" for i, item in enumerate(items))

def mask_phone_last4(digits):
    last4 = digits[-4:]
    return f"***-***-{last4}"

def mask_phone_all_but_last(digits, keep):
    if keep <= 0:
        return "*" * len(digits)
    if keep >= len(digits):
        return digits
    return "*" * (len(digits) - keep) + digits[-keep:]

def mask_phone_middle(digits):
    if len(digits) <= 5:
        return "*" * len(digits)
    return digits[:3] + "*" * (len(digits) - 5) + digits[-2:]

def mask_formatted_phone(phone):
    parts = phone.split("-")
    parts[1] = "*" * len(parts[1])
    return "-".join(parts)

def mask_phone_intl(phone):
    parts = phone.split("-")
    masked = [parts[0]] + ["*" * len(p) for p in parts[1:-1]] + [parts[-1]]
    return "-".join(masked)

def mask_phone_custom_char(digits, ch):
    if len(digits) <= 4:
        return digits
    return ch * (len(digits) - 4) + digits[-4:]

def mask_phone_with_ext(phone_ext):
    if " x" in phone_ext:
        main, ext = phone_ext.split(" x", 1)
        ext_part = " x" + ext
    else:
        main, ext_part = phone_ext, ""
    digits_only = main.replace("-", "")
    last4 = digits_only[-4:]
    masked_main = "*" * (len(digits_only) - 4) + last4
    result_chars = []
    di = 0
    for c in main:
        if c == "-":
            result_chars.append("-")
        else:
            result_chars.append(masked_main[di])
            di += 1
    return "".join(result_chars) + ext_part

def partial_reveal_phone(digits, keep_first, keep_last):
    n = len(digits)
    if keep_first + keep_last >= n:
        return digits
    return digits[:keep_first] + "*" * (n - keep_first - keep_last) + digits[-keep_last:]
